def can_reach_border(r, c):
    """Can reach any border by moving through non-5 cells?"""
    # BFS from (r,c), can move in 4 directions through non-5 cells
    queue = [(r, c)]
    visited = {(r, c)}

    while queue:
        curr_r, curr_c = queue.pop(0)

        if curr_r == 0 or curr_r == 14 or curr_c == 0 or curr_c == 4:
            return True

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < 15 and 0 <= nc < 5 and (nr, nc) not in visited:
                if demo_input[nr][nc] != 5:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return False

