def predict_v7():
    result = [row[:] for row in demo_input]

    # Pre-compute which rows are long-run rows
    long_run_rows = set()
    for r in range(15):
        row = demo_input[r]
        max_run = 0
        curr_run = 0
        for c in range(5):
            if row[c] == 5:
                curr_run += 1
                max_run = max(max_run, curr_run)
            else:
                curr_run = 0
        if max_run >= 4:
            long_run_rows.add(r)

    for c in range(5):
        five_rows = [r for r in range(15) if demo_input[r][c] == 5]

        for i in range(len(five_rows) - 1):
            r1, r2 = five_rows[i], five_rows[i+1]

            # Check all zeros between
            all_zeros = all(demo_input[r][c] == 0 for r in range(r1 + 1, r2))
            if not all_zeros:
                continue

            def run_including_col(r, c):
                for start in range(max(0, c-2), min(5, c+1)):
                    end = start
                    while end + 1 < 5 and demo_input[r][end+1] == 5:
                        end += 1
                    if start <= c <= end and end - start + 1 >= 3:
                        return True
                return False

            cond_upper_run = run_including_col(r1, c)
            cond_lower_run = run_including_col(r2, c)

            # Condition: both have runs including this column
            if not (cond_upper_run and cond_lower_run):
                continue

            # Condition: at least one boundary is a long-run row
            if not ((r1 in long_run_rows) or (r2 in long_run_rows)):
                continue

            print(f"Col {c}: ({r1},{r2}) would fill (long={r1 in long_run_rows or r2 in long_run_rows})")

            for r in range(r1 + 1, r2):
                if demo_input[r][c] == 0:
                    result[r][c] = 8

    return result

