            if grid[r][nc] != 0:
                blocked_left = True
                break

        for step in range(1, num_cols - c):
            nc = c + step
            if nc >= num_cols:
                break
            if grid[r][nc] != 0:
                blocked_right = True
                break

        return blocked_left or blocked_right

    elif axis == 'vertical':
        # Check if blocked up OR down
        blocked_up = False
        blocked_down = False

        for step in range(r + 1):
            nr = r - step
            if nr < 0:
                break
            if grid[nr][c] != 0:
                blocked_up = True
                break

        for step in range(1, num_rows - r):
            nr = r + step
            if nr >= num_rows:
                break
            if grid[nr][c] != 0:
                blocked_down = True
                break

        return blocked_up or blocked_down

