def apply_fixed_rule(grid_in, height):
    predictions = list(map(list, grid_in))

    for r in range(height):
        if r >= height // 2:
            continue

        row = predictions[r]
        num_cols = len(row)
        five_locs = [c for c,v in enumerate(row) if v == 5]

        if not five_locs:
            continue

        # Fill gaps between consecutive 5s with 7
        # BUT: Don't fill gaps before the FIRST five (when prev==-1)
        prev = -1
        for curr in five_locs:
            # Only fill if there's a gap AND this isn't before the first five
            if curr > prev + 1 and prev != -1:
                gap_start, gap_end = prev+1, curr-1
                for c in range(gap_start, gap_end + 1):
                    if predictions[r][c] == 0:
                        predictions[r][c] = 7

            prev = curr

        # Fill after last 5 with 8
        last_five = five_locs[-1]
        for c in range(last_five + 1, num_cols):
            if predictions[r][c] == 0:
                predictions[r][c] = 8

    return predictions

